import json
import logging
import os
import re

from pathlib import Path

from taf.internal.managedobject import ManagedObject
from taf.converters.base import ConverterComponent

from .tti_event_reader import TtiEventReader

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class EventDecoderConverter(ManagedObject, ConverterComponent):
    """
    Converter of TTI trace pcap/bin files to json/csv format.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(
            self,
            input_file_path,
            local_executor,
            output_file_path="output",
            output_file_format="legacyCsv",
            tti_dec_path="/opt/tti-dec/tti-dec-bin",
            filter_func=None,
            tti_dec_venv_path="/opt/tti-dec/venv",
            excel_csv_options="",
            eventdecoder_options="",
            eventdecoder_stdout_path=None,
            **kwargs):
        """
        Create a converter to convert TTI trace pcap/bin files to json/csv format.

        :param str input_file_path:
            input file path
        :param LocalExecutor local_executor:
            local executor for executing conversion commands
        :param Optional[str] output_file_path:
            output file path, default is "output"
        :param Optional[str] output_file_format:
            output file format can be "json", "legacyCsv" or "excelCsv", default is "legacyCsv"
        :param Optional[str] tti_dec_path:
            path where tti-dec is installed, default is "/opt/tti-dec/tti-dec-bin"
        :param Optional[Union[Callable[[dict],bool],str]] filter_func: filter for TTI events (for json or excelCsv):

            - regular expression to be matched with the TTI event type or
            - callable which checks for a TTI event (dict) whether it shall be kept or
            - name of a Robot keyword which checks for a TTI event (dict) whether it shall be kept

            default is no filtering
        :param Optional[str] tti_dec_venv_path:
            path of virtualenv to be used for tti-dec Python scripts, default is "/opt/tti-dec/venv"
        :param Optional[str] excel_csv_options:
            options for ExcelCsvGenerator.py script (e.g. "-d combineDlAndUl -s 100"),
            if output_file_format is "excelCsv", default is ""
        :param Optional[str] eventdecoder_options: options for eventDecoder script (e.g. "--split 20000000"),
        :param Optional[str] eventdecoder_stdout_path: path to store the stdout of eventDecoder script, default is None
            which means stdout is not stored
        """

        super(EventDecoderConverter, self).__init__(**kwargs)

        self._input_file_path = input_file_path
        self._output_file_path = Path(output_file_path)
        self._output_file_format = output_file_format
        self._tti_dec_path = tti_dec_path
        self._tti_dec_venv_path = tti_dec_venv_path
        self._excel_csv_options = excel_csv_options
        self._filter_func = filter_func
        self._local_executor = local_executor
        self.add_prerequisite(self._local_executor)
        self._eventdecoder_options = " " + eventdecoder_options if eventdecoder_options else ""
        self._eventdecoder_stdout_path = eventdecoder_stdout_path

    def convert(self):
        """
        Convert TTI trace pcap/bin files to json/csv format.
        """

        output_file_format = "json" if self._output_file_format == "excelCsv" else self._output_file_format
        self._output_file_path.parent.mkdir(parents=True, exist_ok=True)
        if self._filter_func is None:
            self._convert_by_eventdecoder_without_filtering(output_file_format)
        else:
            self._convert_by_eventdecoder_with_filtering(output_file_format)

        if self._output_file_format == "excelCsv":
            self._convert_by_excel_csv_generator()

    def _open_filter_input(self, file_name):
        return open(file_name, "rb")

    def _open_filter_output(self, file_name):
        return open(file_name, "wb")

    def _convert_by_eventdecoder_without_filtering(self, output_file_format):

        command = (
            '''"$(find '{tti_dec_path}' -name eventDecoder)" '{input_file_path}' '{output_file_path}' '''
            '''--format {output_file_format}{eventdecoder_options}''').format(
            tti_dec_path=self._tti_dec_path,
            input_file_path=self._input_file_path,
            output_file_path=self._output_file_path,
            output_file_format=output_file_format,
            eventdecoder_options=self._eventdecoder_options)

        stdout = self._local_executor.execute(command)
        if self._eventdecoder_stdout_path:
            self._write_eventdecoder_stdout(stdout)

    def _convert_by_eventdecoder_with_filtering(self, output_file_format):
        fifo_file_name = self._output_file_path.with_suffix(".json")
        output_file_path = Path(os.path.splitext(fifo_file_name)[0])

        command = (
            '''"$(find '{tti_dec_path}' -name eventDecoder)" '{input_file_path}' '{output_file_path}' '''
            '''--format {output_file_format}{eventdecoder_options} > {eventdecoder_stdout_path}''').format(
            tti_dec_path=self._tti_dec_path,
            input_file_path=self._input_file_path,
            output_file_path=output_file_path,
            output_file_format=output_file_format,
            eventdecoder_options=self._eventdecoder_options,
            eventdecoder_stdout_path=self._eventdecoder_stdout_path if self._eventdecoder_stdout_path else "/dev/null"
        )
        temp_output_path = self._output_file_path.with_name(
            self._output_file_path.stem + "_temp").with_suffix(".json")

        self._local_executor.execute(
            "rm -f '{fifo_file_name}' ; mkfifo '{fifo_file_name}'".format(
                fifo_file_name=fifo_file_name))
        process = self._local_executor.start(command)
        with self._open_filter_input(fifo_file_name) as file_in:
            with self._open_filter_output(temp_output_path) as file_out:
                file_out.write(b'{\n"events": [')
                no_tti_event_written = True
                for event in TtiEventReader(file_obj=file_in):
                    if self._filter_func(event):
                        file_out.write(b"\n" if no_tti_event_written else b",\n")
                        file_out.write(json.dumps(event, indent=4).encode("utf-8"))
                        no_tti_event_written = False
                file_out.write(b'\n]}')

        process.wait()

        self._local_executor.execute(
            "mv '{temp_output_path}' '{fifo_file_name}'".format(
                fifo_file_name=fifo_file_name,
                temp_output_path=temp_output_path))

    def _convert_by_excel_csv_generator(self):
        # match only L2-PS json files
        pattern = re.compile(rf"^{self._output_file_path.name}(_\d+)?\.json$")
        matched_json_files = [file for file in sorted(self._output_file_path.parent.glob("*.json"))
                              if pattern.match(file.name)]
        for intermediate_json in matched_json_files:
            command = (
                """source '{tti_dec_venv_path}'/bin/activate ; """
                """python3 -W ignore::FutureWarning "$(find '{tti_dec_path}' -name ExcelCsvGenerator.py)" """
                """{excel_csv_options} '{intermediate_json}' '{output_file_path}'""".format(
                    tti_dec_venv_path=self._tti_dec_venv_path,
                    tti_dec_path=self._tti_dec_path,
                    excel_csv_options=self._excel_csv_options,
                    intermediate_json=intermediate_json,
                    output_file_path=self._output_file_path))
            self._local_executor.execute(command)
            self._local_executor.execute(
                "rm -f '{intermediate_json}'".format(
                    intermediate_json=intermediate_json))

    def _write_eventdecoder_stdout(self, stdout):
        with open(self._eventdecoder_stdout_path, "wb") as stdout_file:
            stdout_file.write(stdout)
        logger.info("eventDecoder stdout written to {path}".format(path=self._eventdecoder_stdout_path))
